<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';require_once __DIR__.'/includes/ranked.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];
$sort=(string)($_GET['sort']??'recent');$orders=['recent'=>'last_battle DESC','most'=>'meetings DESC,last_battle DESC','least'=>'meetings ASC,last_battle DESC'];if(!isset($orders[$sort]))$sort='recent';$search=substr(trim((string)($_GET['q']??'')),0,45);$kind=(string)($_GET['kind']??'');if(!in_array($kind,['','player','ai'],true))$kind='';
$union='SELECT defender_id rival_id,result,created_at,1 attacking FROM nxt_ranked_matches WHERE attacker_id=? UNION ALL SELECT attacker_id rival_id,CASE result WHEN "win" THEN "loss" WHEN "loss" THEN "win" ELSE "draw" END result,created_at,0 attacking FROM nxt_ranked_matches WHERE defender_id=?';
$aggregate='SELECT r.rival_id,COUNT(*) meetings,SUM(r.result="win") player_wins,SUM(r.result="loss") player_losses,SUM(r.result="draw") draws,SUM(r.attacking=0) incoming,MAX(r.created_at) last_battle FROM ('.$union.') r GROUP BY r.rival_id';
$rows=dn_rows($db,'SELECT x.*,m.username,m.created_avatar,IF(b.owner_id IS NULL,0,1) is_bot FROM ('.$aggregate.') x JOIN members m ON m.id=x.rival_id LEFT JOIN nxt_bots b ON b.owner_id=m.id ORDER BY '.$orders[$sort],[$uid,$uid]);$all=$rows;$current=null;$most=null;$least=null;$meetings=0;$incoming=0;foreach($all as $r){$meetings+=(int)$r['meetings'];$incoming+=(int)$r['incoming'];if(!$current||$r['last_battle']>$current['last_battle'])$current=$r;if(!$most||$r['meetings']>$most['meetings'])$most=$r;if(!$least||$r['meetings']<$least['meetings'])$least=$r;}
$rows=array_values(array_filter($rows,fn($r)=>($search===''||stripos($r['username'],$search)!==false)&&($kind===''||($kind==='ai'?(bool)$r['is_bot']:!$r['is_bot']))));$total=count($rows);$pages=max(1,(int)ceil($total/24));$page=max(1,min($pages,(int)($_GET['page']??1)));$rows=array_slice($rows,($page-1)*24,24);
pv_page_start('Tamer Rivals','tamer_rivals.php',true);?>
<div class="pv-game-layout"><?php pv_game_side_menu('tamer_rivals.php');?><main class="pv-main-column"><section class="pv-page bp-page"><header class="bp-hero"><div><span class="pv-eyebrow">YOUR BATTLE PARK STORY</span><h1>Know your rivals.</h1><p>Every rematch builds a rivalry. Track the tamers you meet most, the challengers on your trail, and your latest encounters.</p><nav class="bp-tabs" aria-label="Battle Park"><a href="<?=pv_h(pv_url('battle_arena.php'))?>">Battle Park</a><a class="active" href="<?=pv_h(pv_url('tamer_rivals.php'))?>">Tamer rivals</a><a href="<?=pv_h(pv_url('ai_activity.php'))?>">AI activity</a></nav></div><div class="bp-rival-total"><b><?=count($all)?></b><span>RIVALS MET</span><small><?=$meetings?> matches · <?=$incoming?> incoming challenges</small></div></header>
<div class="bp-rival-spotlights"><?php foreach([['Latest rival',$current],['Most encountered',$most],['Least encountered',$least]] as [$label,$r]):?><article class="bp-card"><span class="pv-eyebrow"><?=pv_h($label)?></span><?php if($r):?><div class="bp-rival-header"><img src="<?=pv_h(nxt_skin_url((int)$r['created_avatar']))?>" alt=""><div><span class="bp-badge <?=$r['is_bot']?'is-ai':'is-human'?>"><?=$r['is_bot']?'AI TAMER':'PLAYER'?></span><h3><?=pv_h($r['username'])?></h3><p><?=(int)$r['meetings']?> encounters · <?=(int)$r['incoming']?> incoming</p></div></div><div class="bp-rival-record"><strong><?=(int)$r['player_wins']?> <small>WINS</small></strong><strong><?=(int)$r['player_losses']?> <small>LOSSES</small></strong><strong><?=(int)$r['draws']?> <small>DRAWS</small></strong></div><?php else:?><p class="pv-empty">Enter Battle Park to meet your first rival.</p><?php endif;?></article><?php endforeach;?></div>
<section class="bp-card"><div class="bp-section-title"><h2>Your rival network</h2><span class="bp-fine">Your results, across all seasons</span></div><form method="get" class="bp-filter bp-rival-filter"><label><span>Find a tamer</span><input name="q" maxlength="45" value="<?=pv_h($search)?>" placeholder="Tamer name"></label><label><span>Sort rivals</span><select name="sort"><option value="recent" <?=$sort==='recent'?'selected':''?>>Most recent</option><option value="most" <?=$sort==='most'?'selected':''?>>Most encountered</option><option value="least" <?=$sort==='least'?'selected':''?>>Least encountered</option></select></label><label><span>Tamer type</span><select name="kind"><option value="">Everyone</option><option value="player" <?=$kind==='player'?'selected':''?>>Players</option><option value="ai" <?=$kind==='ai'?'selected':''?>>AI tamers</option></select></label><button class="bp-secondary">Find rivals</button></form>
<?php if(!$rows):?><div class="pv-empty"><?=$all?'No rivals match your search.':'Your rival network begins with your first ranked match.'?> <a href="<?=pv_h(pv_url('battle_arena.php'))?>">Enter Battle Park →</a></div><?php endif;?><div class="bp-rival-grid"><?php foreach($rows as $r):?><article><div class="bp-rival-header"><img src="<?=pv_h(nxt_skin_url((int)$r['created_avatar']))?>" alt=""><div><span class="bp-badge <?=$r['is_bot']?'is-ai':'is-human'?>"><?=$r['is_bot']?'AI TAMER':'PLAYER'?></span><h3><?=pv_h($r['username'])?></h3><small>Last battle <?=gmdate('d M · H:i',(int)$r['last_battle'])?> UTC</small></div></div><div class="bp-rival-record"><strong><?=(int)$r['player_wins']?> <small>W</small></strong><strong><?=(int)$r['player_losses']?> <small>L</small></strong><strong><?=(int)$r['meetings']?> <small>MATCHES</small></strong></div><p><?=(int)$r['incoming']?> challenges against your defense team</p></article><?php endforeach;?></div><nav class="bp-pager" aria-label="Rival pages"><?php if($page>1):?><a href="?<?=pv_h(http_build_query(['q'=>$search,'kind'=>$kind,'sort'=>$sort,'page'=>$page-1]))?>">← Previous</a><?php endif;?><span>Page <?=$page?> of <?=$pages?></span><?php if($page<$pages):?><a href="?<?=pv_h(http_build_query(['q'=>$search,'kind'=>$kind,'sort'=>$sort,'page'=>$page+1]))?>">Next →</a><?php endif;?></nav></section><p class="bp-fine bp-note">Most and least encountered compare rivals you have actually battled. Defense matches count as incoming challenges. Matchmaking finds opponents near your team strength and season points.</p>
</section></main></div><?php pv_page_end();?>
